def _test_str():
    print('type: str')
    s1 = 'Hello world.'
    print(s1)
    s2 = """Hello \
        world."""
    print(s2)

    # f-strings
    print(f'{"bar":>8s}')
    print(f'{1 / 7:.2%}')

    # r-string - raw strings
    print(r'C:\temp\file.txt')

    # u-string - unicode literals
    print(u'A \u00c4\u00d6\u00dc')

    # octal and hexadecimal escapes
    print('\110\145\154\154\157')
    print('\x48\x65\x6C\x6C\x6F')
    print('{:o}'.format(8))
    print('{:#X}'.format(9))


def _test_unicode():
    print('type: Unicode')
    print('Hello\tworld!')
    print('Hello\nworld!')
    print('Hello\rworld!')

    # u-escape sequences
    print(u'\N{BLACK SPADE SUIT}')


